package com.honorablemobile
import org.junit.Assert.*
import org.junit.Test
import kotlin.random.Random
class VideoRepeatedFootageTest {
 @Test fun noOverlapForSingleDifferentSourcesOrTouchingRanges(){for(c in listOf(listOf(VideoSegment(0,1000)),listOf(VideoSegment(0,1000),VideoSegment(1000,2000)),listOf(VideoSegment(0,2000),VideoSegment(0,2000,sourceId="other")))){val r=VideoRepeatedFootage.inspect(c);assertEquals(0,r.totalPairs);assertTrue(r.pairs.isEmpty());assertEquals(0,r.omittedPairs)}}
 @Test fun partialContainmentAndExactRepeatsAreFound(){val c=listOf(VideoSegment(1000,5000),VideoSegment(3000,7000),VideoSegment(2000,4000),VideoSegment(1000,5000));val r=VideoRepeatedFootage.inspect(c);assertEquals(6,r.totalPairs);assertEquals(1000L,r.pairs.first().startMs);assertEquals(5000L,r.pairs.first().endMs);assertEquals(0,r.pairs.first().first.clipIndex);assertEquals(3,r.pairs.first().second.clipIndex);assertTrue(r.pairs.any{it.startMs==3000L&&it.endMs==4000L})}
 @Test fun speedAwarePositionsIncludeUnrelatedEarlierClipsAndSourceStartOffsets(){val c=listOf(VideoSegment(0,1000,sourceId="other"),VideoSegment(1000,5000,speed=2f),VideoSegment(3000,7000,speed=.5f));val p=VideoRepeatedFootage.inspect(c).pairs.single();assertEquals(3000L,p.startMs);assertEquals(5000L,p.endMs);assertEquals(2000000L,p.first.outputUs);assertEquals(3000000L,p.second.outputUs);assertEquals(1000000L,p.first.overlapPlaybackUs);assertEquals(4000000L,p.second.overlapPlaybackUs);assertEquals(3000L,p.first.sourceMs);assertEquals(3000L,p.second.sourceMs)}
 @Test fun differentLooksCaptionsAndAudioDoNotHideReusedSource(){val c=VideoSegment(0,5000,captions=listOf(VideoCaption(0,1000,"One")));val b=c.copy(speed=1.5f,title="Edited",volume=.2f,audioFade=true,fadeEdges=true,grade=VideoGrade(exposure=1f),layout=VideoLayout(rotation=90),captions=listOf(VideoCaption(1000,2000,"Another")));assertEquals(1,VideoRepeatedFootage.inspect(listOf(c,b)).totalPairs)}
 @Test fun orderedTopListAndTieBreakAreDeterministic(){val c=List(20){VideoSegment(0,1000)};val r=VideoRepeatedFootage.inspect(c);assertEquals(190,r.totalPairs);assertEquals(100,r.pairs.size);assertEquals(90,r.omittedPairs);val expected=(0..19).flatMap{i->(i+1..19).map{j->i to j}}.take(100);assertEquals(expected,r.pairs.map{it.first.clipIndex to it.second.clipIndex});assertEquals(r,VideoRepeatedFootage.inspect(c))}
 @Test fun laterLongOverlapDisplacesEarlierShortPair(){val c=List(20){VideoSegment(0,1000)}+listOf(VideoSegment(5000,10000),VideoSegment(5000,10000));val r=VideoRepeatedFootage.inspect(c);assertEquals(191,r.totalPairs);assertEquals(20,r.pairs.first().first.clipIndex);assertEquals(21,r.pairs.first().second.clipIndex);assertEquals(5000L,r.pairs.first().endMs-r.pairs.first().startMs)}
 @Test fun maximumThousandClipReportHasExactCountAndBoundedOutput(){val r=VideoRepeatedFootage.inspect(List(1000){VideoSegment(0,1000)});assertEquals(499500,r.totalPairs);assertEquals(100,r.pairs.size);assertEquals(499400,r.omittedPairs)}
 @Test fun independentBruteForceReferenceMatchesRandomSourcesSpeedsAndSpans(){val rng=Random(126);repeat(75){val c=List(2+rng.nextInt(45)){val start=rng.nextLong(0,5000);VideoSegment(start,start+rng.nextLong(1,8000),speed=listOf(.5f,1f,1.5f,2f)[rng.nextInt(4)],sourceId="source${rng.nextInt(4)}")};val expected=mutableListOf<Triple<Int,Int,Long>>();for(i in c.indices)for(j in i+1 until c.size){val length=minOf(c[i].endMs,c[j].endMs)-maxOf(c[i].startMs,c[j].startMs);if(c[i].sourceId==c[j].sourceId&&length>0)expected+=Triple(i,j,length)};val ordered=expected.sortedWith(compareByDescending<Triple<Int,Int,Long>>{it.third}.thenBy{it.first}.thenBy{it.second});val r=VideoRepeatedFootage.inspect(c);assertEquals(expected.size,r.totalPairs);assertEquals(ordered.take(100),r.pairs.map{Triple(it.first.clipIndex,it.second.clipIndex,it.endMs-it.startMs)});for(p in r.pairs)for(o in listOf(p.first,p.second)){val clip=c[o.clipIndex];assertTrue(o.sourceMs in clip.startMs until clip.endMs);assertTrue(o.outputUs>=c.take(o.clipIndex).sumOf{it.durationUs});assertTrue(o.outputUs<c.take(o.clipIndex+1).sumOf{it.durationUs});assertEquals(c.take(o.clipIndex).sumOf{it.durationUs}+((o.sourceMs-clip.startMs)*1000.0/clip.speed).toLong(),o.outputUs)}}}
 @Test fun halfOpenOneMillisecondOverlapIsNotRoundedAway(){val p=VideoRepeatedFootage.inspect(listOf(VideoSegment(0,1000,speed=2f),VideoSegment(999,2000,speed=2f))).pairs.single();assertEquals(999L,p.startMs);assertEquals(1000L,p.endMs);assertEquals(500L,p.first.overlapPlaybackUs)}
 @Test fun inspectionIsReadOnlyAndDoesNotCreateUndo(){val project=VideoEditProject(10000);project.restore(listOf(VideoSegment(0,5000),VideoSegment(3000,7000)));val before=project.segments;VideoRepeatedFootage.inspect(before);assertSame(before,project.segments);assertFalse(project.canUndo)}
 @Test fun invalidCountsTimingBoundsAndCancelledInspectionFail(){assertThrows(IllegalArgumentException::class.java){VideoRepeatedFootage.inspect(emptyList())};assertThrows(IllegalArgumentException::class.java){VideoRepeatedFootage.inspect(List(1001){VideoSegment(0,1)})};assertThrows(IllegalArgumentException::class.java){VideoRepeatedFootage.inspect(listOf(VideoSegment(0,Int.MAX_VALUE.toLong()+1)))};var count=0;assertThrows(IllegalStateException::class.java){VideoRepeatedFootage.inspect(List(1000){VideoSegment(0,1000)}){if(++count==4)error("stale")}};assertEquals(4,count)}
}
